# frozen_string_literal: true

require "digest"
require "json"

module CJKIndex
  # Folds text so that spelling variants a reader treats as "the same" compare
  # equal: NFKC (full-width -> half-width etc.), lowercase, katakana ->
  # hiragana, character variants from the selected tables, and the iteration
  # mark 々 expanded to the preceding character.
  #
  # The same rules run in the browser (see Runtime), so an index built here
  # and a query typed there are folded identically.
  #
  # Variant tables (data/*.tsv, regenerated by script/variant_tables.rb):
  #   ja       Japanese old forms and glyph variants -> one form (圖 -> 図),
  #            from the Joyo and Jinmeiyo kanji lists and Unihan. Default.
  #   zh       Traditional -> Simplified Chinese, from OpenCC. Opt in: it also
  #            merges characters that are distinct in Japanese (後 and 后).
  #   zh-safe  The pairs of zh that are one-to-one both ways (圖 -> 图 but
  #            not 後 -> 后 or 發/髮 -> 发). Opt in.
  #   ko       Old Hangul in the Hanyang Private Use Area -> standard jamo
  #            sequences (one character -> several). Opt in.
  # With several tables, characters linked by any table fold to one form,
  # preferring the target of the table listed first: with [ja, zh],
  # 圖, 図 and 图 all become 図.
  # Any other entry names a table file of your own, relative to base (the
  # site's folder for Jekyll and Bridgetown, the current folder otherwise).
  # The index records the entry as written, not the resolved path.
  #
  # Table format: UTF-8 lines "variant<TAB>folded", optionally followed by
  # another tab and a comment column; lines starting with "#" are comments.
  # "folded" may be several characters.
  #
  # Your own table is one group per line, tab-separated: the form to fold to,
  # then its variants, one character each (the format of the itaiji lists
  # that collection databases keep). Each cell is folded first (NFKC,
  # lowercase, katakana -> hiragana), so a compatibility ideograph such as
  # U+F900 joins the group of the character NFKC makes of it.
  class Normalizer
    DATA_DIR = File.expand_path("../../data", __dir__)
    TABLES = {
      "ja" => "ja-kyujitai.tsv",
      "zh" => "zh-hant-hans.tsv",
      "zh-safe" => "zh-hant-hans-safe.tsv",
      "ko" => "ko-hanyang-pua.tsv"
    }.freeze
    DEFAULT_TABLES = %w[ja].freeze

    # Katakana ァ (U+30A1) .. ヶ (U+30F6) map to hiragana by subtracting 0x60.
    KATAKANA_FIRST = 0x30A1
    KATAKANA_LAST = 0x30F6
    KANA_OFFSET = 0x60
    ITERATION_MARK = "々"

    def self.default
      @default ||= new
    end

    # Pairs [variant, folded] of a built-in table, or of a table file of your
    # own (a name that is not built in, resolved against base).
    def self.read_table(name, base: Dir.pwd)
      return read_groups(name, File.expand_path(name, base)) unless TABLES.key?(name)

      lines(File.join(DATA_DIR, TABLES[name])).map { |_, line| line.split("\t")[0, 2] }
    end

    def self.lines(path) # :nodoc:
      File.readlines(path, chomp: true, encoding: "UTF-8").each_with_index
          .reject { |line, _| line.strip.empty? || line.start_with?("#") }
          .map { |line, i| [i + 1, line.delete_prefix("\uFEFF")] }
    end

    def self.read_groups(name, path) # :nodoc:
      unless File.file?(path)
        raise ArgumentError, "unknown variant table #{name.inspect}: not one of #{TABLES.keys.join(', ')}, " \
                             "and no file at #{path}"
      end

      plain = new(tables: [])
      lines(path).flat_map do |number, line|
        target, *variants = line.split("\t").map(&:strip).reject(&:empty?).map { |cell| plain.normalize(cell) }
        variants = variants.uniq.reject { |v| v == target } # NFKC may already fold a cell (㍿)
        variants.each do |v|
          next if v.length == 1

          raise ArgumentError, "#{name}:#{number}: #{v.inspect} is not one character; " \
                               "only the first cell (the form to fold to) may be longer"
        end
        variants.map { |v| [v, target] }
      end
    end

    attr_reader :tables, :variants, :digest

    KATAKANA = "#{KATAKANA_FIRST.chr(Encoding::UTF_8)}-#{KATAKANA_LAST.chr(Encoding::UTF_8)}"
    HIRAGANA = "#{(KATAKANA_FIRST - KANA_OFFSET).chr(Encoding::UTF_8)}-#{(KATAKANA_LAST - KANA_OFFSET).chr(Encoding::UTF_8)}"

    def initialize(tables: DEFAULT_TABLES, base: Dir.pwd)
      @tables = tables.map(&:to_s).uniq.freeze
      @base = base
      @variants = build_variants.freeze
      keys = @variants.keys.select { |k| k.length == 1 }
      @variant_chars = keys.empty? ? nil : Regexp.new("[#{keys.map { |k| format('\\u{%x}', k.ord) }.join}]")
      # What the tables fold, not their names: an index built with an older
      # "ja" table must not be read with a newer one.
      @digest = Digest::SHA256.hexdigest(JSON.generate(@variants.sort)).slice(0, 16).freeze
    end

    # Raises unless data (an index) was built with the same tables as this
    # normalizer. An index without a digest predates 1.0: it still loads, but
    # it folded with older tables and should be rebuilt.
    def check!(data)
      if tables != data["variants"]
        raise ArgumentError, "cjk_index: index built with variant tables #{data['variants'].inspect} " \
                             "but this normalizer folds with #{tables.inspect}; rebuild both together"
      end
      return if data["variant_digest"].nil? || data["variant_digest"] == digest

      raise ArgumentError, "cjk_index: index built with other contents of the variant tables " \
                           "#{tables.inspect} (an older cjk_index?); rebuild it"
    end

    # Character by character: katakana to hiragana, then the variant tables,
    # then 々 to the (folded) character before it. Done as passes over the
    # whole string, which gives the same result as one loop over the
    # characters (the loop in runtime.js) and is several times faster in Ruby.
    def normalize(text)
      return "" if text.nil?

      s = text.to_s.unicode_normalize(:nfkc).downcase
      s = s.tr(KATAKANA, HIRAGANA)
      # 々 repeats the folded character before it, which may be several
      # characters (ko): fold one character at a time, as runtime.js does
      return iterate(s) if s.include?(ITERATION_MARK)

      @variant_chars ? s.gsub(@variant_chars, @variants) : s
    end

    private

    def iterate(s)
      prev = nil
      s.each_char.map do |ch|
        ch = @variants.fetch(ch, ch)
        ch = prev if ch == ITERATION_MARK && prev
        prev = ch
      end.join
    end

    # Union-find over all pairs; each class folds to the target preferred by
    # the earliest table (lowest code point among equals, for determinism).
    def build_variants
      parent = {}
      find = lambda do |x|
        parent[x] ||= x
        parent[x] = find.call(parent[x]) unless parent[x] == x
        parent[x]
      end
      rank = {}
      @tables.each_with_index do |name, priority|
        self.class.read_table(name, base: @base).each do |from, to|
          parent[find.call(from)] = find.call(to)
          rank[to] = [rank.fetch(to, [priority, to.ord]), [priority, to.ord]].min
        end
      end
      classes = parent.keys.group_by { |x| find.call(x) }
      classes.each_value.with_object({}) do |members, map|
        canonical = members.min_by { |m| rank.fetch(m, [Float::INFINITY, m.ord]) }
        members.each { |m| map[m] = canonical unless m == canonical }
      end
    end
  end
end
